#!/usr/bin/env python3
"""Prepare an isolated offline wrapper; never mutate frozen serving sources."""
import argparse,hashlib,json,os,pathlib,shutil
ROOT=pathlib.Path(__file__).resolve().parents[1]
WRAPPER=r'''package recommend
import("context";"fmt";"sort";"strings")
type OfflineSelection struct {Policy string `json:"policy"`;Limit int `json:"limit"`;Selected []string `json:"selected"`;Complete bool `json:"complete"`;Details any `json:"details"`}
type OfflineReduction struct {Mode string `json:"mode"`;Complete bool `json:"complete"`;OriginalCandidates int `json:"original_candidates"`;OriginalPatterns int `json:"original_patterns"`;RetainedCandidates int `json:"retained_candidates"`;RetainedPatterns int `json:"retained_patterns"`;LostPatterns int `json:"lost_patterns"`;MultiPatternEqualVectorGroupsBefore int `json:"multi_pattern_equal_vector_groups_before"`;MultiPatternEqualVectorGroupsAfter int `json:"multi_pattern_equal_vector_groups_after"`;Retained []string `json:"retained_ids"`;Excluded map[string]string `json:"excluded"`}
func offlineReduction(fs,pool []Feature,excluded map[string]string,mode string,complete bool)*OfflineReduction{
 patterns:=map[string]bool{};retained:=map[string]bool{};before:=map[[3]int64]map[string]bool{};after:=map[[3]int64]map[string]bool{};out:=&OfflineReduction{Mode:mode,Complete:complete,OriginalCandidates:len(fs),RetainedCandidates:len(pool),Retained:[]string{},Excluded:excluded}
 for _,f:=range fs{patterns[f.Pattern]=true;v:=vector(f);if before[v]==nil{before[v]=map[string]bool{}};before[v][f.Pattern]=true}
 for _,f:=range pool{retained[f.Pattern]=true;out.Retained=append(out.Retained,f.Identity);v:=vector(f);if after[v]==nil{after[v]=map[string]bool{}};after[v][f.Pattern]=true};sort.Strings(out.Retained);out.OriginalPatterns=len(patterns);out.RetainedPatterns=len(retained);for p:=range patterns{if !retained[p]{out.LostPatterns++}};for _,ps:=range before{if len(ps)>1{out.MultiPatternEqualVectorGroupsBefore++}};for _,ps:=range after{if len(ps)>1{out.MultiPatternEqualVectorGroupsAfter++}};return out
}
// Independently reconstructed features only; no new routing/feasibility claim.
func ReplayFeatureControls(ctx context.Context,fs []Feature,cfg ChoiceConfig)(out []OfflineSelection,reduction *OfflineReduction,err error){
 if err=cfg.Validate();err!=nil{return};if len(fs)>cfg.MaxCandidates{return nil,nil,ErrSelectionBudget};seen:=map[string]bool{};for _,f:=range fs{if f.Identity==""||seen[f.Identity]{return nil,nil,fmt.Errorf("duplicate/empty replay identity")};seen[f.Identity]=true};fs=append([]Feature{},fs...);sort.Slice(fs,func(i,j int)bool{return fs[i].Identity<fs[j].Identity})
 if cfg.Bounded!=nil{var c *ContinuousChoices;c,err=SelectBounded(ctx,fs,cfg);if c!=nil{pool:=[]Feature{};for _,f:=range fs{if _,excluded:=c.Exclusions[f.Identity];!excluded{pool=append(pool,f)}};mode:="bounded_score_only_representatives";if cfg.Bounded.DistinctPatterns{mode="bounded_full_pattern_aware_representatives"};reduction=offlineReduction(fs,pool,c.Exclusions,mode,c.RetainedCandidates==len(pool));for _,s:=range c.Selections{out=append(out,OfflineSelection{Policy:c.Policy,Limit:s.Limit,Selected:s.Selected,Complete:c.Complete&&s.Complete,Details:s})}};return}
 limits:=cfg.DeliveryLimits;if len(limits)==0{limits=[]int{3}}
 if cfg.DeliveryPolicy=="pattern_anchors_v1"{for _,k:=range limits{s:=selectFeatures(fs,k,300);if reduction==nil{pool:=[]Feature{};excluded:=map[string]string{};for _,f:=range fs{why:=s.Decisions[f.Identity];if why=="capacity"||strings.HasPrefix(why,"selected_"){pool=append(pool,f)}else{excluded[f.Identity]=why}};reduction=offlineReduction(fs,pool,excluded,"pattern_envelope_300_and_scalar_dominance_before_anchor_capacity",true)};out=append(out,OfflineSelection{Policy:"pattern_anchors_v1",Limit:k,Selected:s.Selected,Complete:true,Details:s})};return}
 excluded:=map[string]string{};pool:=choiceRepresentatives(fs,excluded);reduction=offlineReduction(fs,pool,excluded,"finite20_score_only_equal_vector_and_monotone_dominance",true);for _,g:=range cfg.Groups{for _,k:=range limits{var ids []int;var states int;ids,states,err=minimax(ctx,pool,g.Preferences,k,cfg.MaxSubsets);if err!=nil{return};s:=describeChoice(pool,g.Preferences,ids,"preference_minimax",k);s.Complete=true;s.PoolOptimal=true;s.EvaluatedSubsets=states;out=append(out,OfflineSelection{Policy:"finite_preferences_v2",Limit:k,Selected:s.Selected,Complete:true,Details:s})}};return
}
'''
MAIN=r'''package main
import("context";"encoding/json";"fmt";"io";"os";"github.com/ertyoii/transit-routing-go/recommend";"github.com/ertyoii/transit-routing-bench/experiment")
func main(){dec:=json.NewDecoder(os.Stdin);dec.DisallowUnknownFields();enc:=json.NewEncoder(os.Stdout);seen:=map[string]bool{};for{var req struct{ID string `json:"request_id"`;Features []recommend.Feature `json:"features"`;Config recommend.ChoiceConfig `json:"config"`};err:=dec.Decode(&req);if err==io.EOF{return};if err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(2)};if req.ID==""||seen[req.ID]{fmt.Fprintln(os.Stderr,"duplicate/empty request ID");os.Exit(2)};seen[req.ID]=true;s,reduction,e:=recommend.ReplayFeatureControls(context.Background(),req.Features,req.Config);message:="";if e!=nil{message=e.Error()};enc.Encode(map[string]any{"request_id":req.ID,"complete":e==nil,"error":message,"selections":s,"reduction":reduction,"build_source_sha256":experiment.BuildSourceSHA256})}}
'''
WRAPPER_TEST=r'''package recommend
import("context";"errors";"testing";"github.com/ertyoii/transit-routing-go/model")
func offlineFeature(id,pattern string,d int64,b int,w int64)Feature{return Feature{Identity:id,Pattern:pattern,Duration:d,Metrics:model.Metrics{Arrival:d,Boardings:b,Transfers:max(0,b-1),WalkingSeconds:w}}}
func TestOfflineReductionPatternAvailability(t *testing.T){fs:=[]Feature{offlineFeature("a","pattern-a",100,1,0),offlineFeature("b","pattern-b",100,1,0),offlineFeature("c","pattern-c",200,2,20)};cfg:=ChoiceConfig{MaxCandidates:100,MaxSubsets:10000,Bounded:&BoundedConfig{MaxTransfer:900,MaxWalk:4,Objective:"absolute",Limits:[]int{3,5},DistinctPatterns:true,MaxCriticalPoints:1000,MaxWork:1000000}};_,r,e:=ReplayFeatureControls(context.Background(),fs,cfg);if e!=nil||r==nil||!r.Complete||r.OriginalPatterns!=3||r.RetainedPatterns!=3||r.RetainedCandidates!=3||r.MultiPatternEqualVectorGroupsBefore!=1||r.MultiPatternEqualVectorGroupsAfter!=1{t.Fatalf("distinct collapse: %+v %v",r,e)};cfg.Bounded=nil;cfg.LeanDelivery=true;cfg.DeliveryPolicy="finite_preferences_v2";cfg.DeliveryLimits=[]int{3,5};cfg.Groups=[]PreferenceGroup{{Name:"one",Preferences:[]Preference{{ID:"zero"}}}};_,r,e=ReplayFeatureControls(context.Background(),fs,cfg);if e!=nil||r==nil||r.RetainedPatterns!=1||r.RetainedCandidates!=1||r.LostPatterns!=2||r.MultiPatternEqualVectorGroupsAfter!=0{t.Fatalf("finite collapse hidden: %+v %v",r,e)};cfg.DeliveryPolicy="pattern_anchors_v1";cfg.Groups=nil;_,r,e=ReplayFeatureControls(context.Background(),fs,cfg);if e!=nil||r.RetainedPatterns!=2||r.RetainedCandidates!=2{t.Fatalf("pattern eligibility wrong: %+v %v",r,e)}}
func TestOfflineReductionGuards(t *testing.T){fs:=[]Feature{offlineFeature("a","a",100,1,0),offlineFeature("b","b",90,2,0)};cfg:=ChoiceConfig{MaxCandidates:100,MaxSubsets:10000,Bounded:&BoundedConfig{MaxTransfer:900,MaxWalk:4,Objective:"absolute",Limits:[]int{3},MaxCriticalPoints:1000,MaxWork:1}};_,r,e:=ReplayFeatureControls(context.Background(),fs,cfg);if !errors.Is(e,ErrSelectionBudget)||r==nil||r.Complete{t.Fatalf("guard falsely qualified reduction: %+v %v",r,e)};cfg.Bounded=nil;cfg.LeanDelivery=true;cfg.DeliveryPolicy="pattern_anchors_v1";_,_,e=ReplayFeatureControls(context.Background(),[]Feature{fs[0],fs[0]},cfg);if e==nil{t.Fatal("duplicate replay identity accepted")}}
'''
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def source_hash(root):
 paths=[]
 for d,dirs,files in os.walk(root):
  dirs[:]=[x for x in dirs if x not in ['.git','.cache','artifacts']]
  for f in files:
   p=pathlib.Path(d)/f;rel=p.relative_to(root).as_posix()
   if f.endswith('.go') or f in ['go.mod','routing.lock.json'] or rel=='vendor/modules.txt':paths.append((rel,p))
 h=hashlib.sha256()
 for rel,p in sorted(paths):b=p.read_bytes();h.update(f'{len(rel.encode())}:{rel}:{len(b)}:'.encode());h.update(b)
 return h.hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--source-root',required=True);p.add_argument('--out-root',required=True);a=p.parse_args();src=pathlib.Path(a.source_root).resolve();out=pathlib.Path(a.out_root).resolve();assert src!=out and not out.exists();base=src/'vendor/github.com/ertyoii/transit-routing-go/recommend';before={x.name:sha(x) for x in sorted(base.glob('*.go'))};src_hash=source_hash(src);shutil.copytree(src,out,ignore=shutil.ignore_patterns('.git','.cache','artifacts'))
 rec=out/'vendor/github.com/ertyoii/transit-routing-go/recommend';(rec/'offline_wrapper.go').write_text(WRAPPER);(rec/'offline_wrapper_test.go').write_text(WRAPPER_TEST);cmd=out/'cmd/offlinefeatureprobe';cmd.mkdir();(cmd/'main.go').write_text(MAIN)
 assert all(sha(rec/name)==digest for name,digest in before.items()),'frozen selector source changed in copy'
 lockpath=out/'routing.lock.json';lock=json.loads(lockpath.read_text());vend=out/'vendor/github.com/ertyoii/transit-routing-go';lock['files']={p.relative_to(vend).as_posix():sha(p) for p in sorted(vend.rglob('*')) if p.is_file()};lock['source_sha256']=hashlib.sha256(json.dumps(lock['files'],sort_keys=True,separators=(',',':')).encode()).hexdigest();lock['origin']+=' Offline-only wrapper exposes unchanged feature selectors; not a serving/timing candidate.';lockpath.write_text(json.dumps(lock,sort_keys=True,indent=2)+'\n')
 policies=[]
 finite=json.loads((ROOT/'selector-quality/configs/finite20-lean-delivery-top3.json').read_text());finite['delivery_limits']=[3,5];policies.append({'id':'finite20_lean_joint_k3k5','config':finite,'role':'strong finite-grid score baseline, not authentic preference model'})
 pattern=json.loads((ROOT/'selector-quality/configs/pattern-anchors-lean-delivery-top3.json').read_text());pattern['delivery_limits']=[3,5];policies.append({'id':'pattern_anchors_joint_k3k5','config':pattern,'role':'original300-score-second envelope control'})
 for obj in ['absolute','normalized']:
  for search in ['greedy','hybrid']:
   for constraint in ['unconstrained','nested','distinct_patterns']:
    cfg=json.loads((ROOT/f'selector-quality/configs/bounded-{obj}-unconstrained-k3k5.json').read_text());cfg['bounded']['exact_when_feasible']=search=='hybrid';cfg['bounded']['nested']=constraint=='nested';cfg['bounded']['distinct_patterns']=constraint=='distinct_patterns';policies.append({'id':f'bounded_{obj}_{search}_{constraint}_joint_k3k5','config':cfg,'role':'offline counterfactual on native candidate input; not serving latency'})
 (out/'OFFLINE_POLICY_MATRIX.json').write_text(json.dumps({'schema':'sg-offline-selector-matrix-v1','policies':policies,'profile_design':'No393/stress/scalar weights enter policy construction; bounded domain and historical finite20 spec only.','request_scope':'joint k3+k5; distinct from original top3-only serving budget','prepared_before_validation_test':True},sort_keys=True,indent=2)+'\n')
 origin={'source_root':str(src),'source_sha256':src_hash,'unchanged_recommend_files':before,'wrapper_sha256':sha(rec/'offline_wrapper.go'),'wrapper_test_sha256':sha(rec/'offline_wrapper_test.go'),'main_sha256':sha(cmd/'main.go'),'preparer_sha256':sha(__file__),'policy_matrix_sha256':sha(out/'OFFLINE_POLICY_MATRIX.json'),'offline_only_not_serving':True};(out/'OFFLINE_ORIGIN.json').write_text(json.dumps(origin,sort_keys=True,indent=2)+'\n');print(json.dumps(origin))
if __name__=='__main__':main()
